    bg = max({v for row in grid for v in row}, key=lambda v: sum(row.count(v) for row in grid))
    pts = [(r,c) for r in range(h) for c in range(w) if grid[r][c] != bg]
    out = [row[:] for row in grid]
    # Identify a repeated diagonal direction among colored markers; for each
    # color with a diagonal run, extend only its line to the grid boundary.
    for color in {grid[r][c] for r,c in pts}:
        ps=[(r,c) for r,c in pts if grid[r][c]==color]
        dirs={}
        for i,(r,c) in enumerate(ps):
            for rr,cc in ps[i+1:]:
                dr,dc=rr-r,cc-c
                if dr and abs(dr)==abs(dc):
                    d=(1 if dr>0 else -1,1 if dc>0 else -1)
                    dirs[d]=dirs.get(d,0)+1
        for (sr,sc),n in dirs.items():
            if n < 1: continue
            for r,c in ps:
                # complete this line in both directions, filling only background
                a,b=r,c
                while 0<=a-sr<h and 0<=b-sc<w: a,b=a-sr,b-sc
                while 0<=a<h and 0<=b<w:
                    if out[a][b]==bg: out[a][b]=color
                    a,b=a+sr,b+sc
    return out
